mapper.sql:
SELECT VFPR.OCODE oCode, VFPR.MARKETID marketId, VFPR.ORGID orgId, VFPR.OTYPE oType, VFPR.GRADEORGID gradeOrgId, MCI.CUSTOMER_NAME gradeOrgName, DATE_FORMAT(VFPR.GRADEDATE,'%Y-%m-%d') gradeDate, DATE_FORMAT(VFPR.NOTICEDATE,'%Y-%m-%d') noticeDate, VFPR.SHORTLONGTERM shortLongTerm, VFPR.GRADERESULT gradeResult, VFPR.INPUTTYPE inputType, VFPR.GRADEEXPECTATION gradeExpectation, VFPR.DIRECTIONCHANGE directionChange, VFPR.ISSUERRATETYPE issuerRateType, VFPR.INNEROUTER innerOuter, IF( @oCode = VFPR.oCode,@rank := @rank + 1,@rank :=1 ) AS rk FROM ( SELECT OCODE, MARKETID, ORGID, OTYPE, GRADEORGID, GRADEDATE, NOTICEDATE, SHORTLONGTERM,
MSTRATINGRESULT02 GRADERESULT,
MSTRATINGRESULT01 GRADERESULT,
INPUTTYPE, GRADEEXPECTATION, DIRECTIONCHANGE, ISSUERRATETYPE, INNEROUTER FROM view_fin_product_rating where 1=1
AND ${sqlSearchString}
AND OCODE = #{oCode,jdbcType=VARCHAR}
AND GRADEORGID = #{gradeOrgId,jdbcType=VARCHAR}
AND GRADEDATE <= STR_TO_DATE(#{gradeDateStr,jdbcType=VARCHAR}, '%Y-%m-%d')
AND GRADEDATE >= STR_TO_DATE(#{gradeDateStart,jdbcType=VARCHAR}, '%Y-%m-%d')
AND GRADEDATE <= STR_TO_DATE(#{gradeDateEnd,jdbcType=VARCHAR}, '%Y-%m-%d')
AND INNEROUTER = #{gradeSourceType,jdbcType=VARCHAR}
AND shortLongTerm = #{shortLongTerm,jdbcType=VARCHAR}
AND oType = #{oType,jdbcType=VARCHAR}
AND MSTRATINGRESULT01 = #{gradeResult,jdbcType=VARCHAR}
) VFPR LEFT JOIN MST_CUSTOMER_INFO MCI ON MCI.CUSTOMER_ID=VFPR.GRADEORGID,( select @rank :=0,@oCode := NULL ) b WHERE 1=1 order by oCode,gradeDate desc

mapper.select:
SELECT * FROM( SELECT TEMP.* , FP.FINPROD_NAME oCodeName FROM (
) TEMP LEFT JOIN FIN_PRODUCT FP ON TEMP.OCODE = FP.FINPROD_MARKET_ID WHERE TEMP.OTYPE = '02'
AND rk = 1
UNION ALL SELECT TEMP.* , MCN.CUSTOMER_NAME oCodeName FROM (
) TEMP LEFT JOIN MST_CUSTOMER_INFO MCN ON TEMP.OCODE = MCN.CUSTOMER_ID WHERE TEMP.OTYPE = '01'
AND rk = 1
) tt ORDER BY tt.gradeDate DESC
